UPDATE LIVROS_NOMES SET CONFERIDO = IF('{{estado}}' = 'PENDENTE', NULL, 'ACEITO'), ESTADO = '{{estado}}', MOTIVO = NULLIF(LEFT('{{motivo}}', 300), ''), CATALOGO_ID = NULL WHERE ID = {{id}} AND ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO') AND '{{estado}}' IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO', 'PENDENTE')